/**
 * Fire a raycast directly from within the worker (for AI agents).
 * Bypasses the sharedRayshoot buffer and performs the raycast immediately.
 *
 * @param {number} shooterIndex - Index of the shooter body
 * @param {string} shooterType - Type of shooter ('dynamic' or 'kinematic')
 * @param {Object} origin - Ray origin { x, y, z }
 * @param {Object} direction - Ray direction { x, y, z } (will be normalized)
 * @param {number} [maxDistance=100] - Maximum raycast distance
 */
export function fireFromPosition(shooterIndex: number, shooterType: string, origin: any, direction: any, maxDistance?: number): void;
/**
 * Process rayshoot requests from the main thread.
 * Reads from sharedRayshoot buffer, performs BVH-accelerated raycasts,
 * and stores hits in physicsState.pendingRayshootHits for event dispatch.
 */
export function rayshootRaycast(): void;
